def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a full separator row or column.
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] not in (0, 2):
            sep = r
            top, bottom = grid[:sep], grid[sep + 1:]
            if top and bottom and len(top) == len(bottom):
                return [[2 if top[i][j] != 0 and bottom[i][j] != 0 else 0
                         for j in range(w)] for i in range(len(top))]

    for c in range(w):
        if all(grid[r][c] == grid[0][c] and grid[0][c] not in (0, 2)
               for r in range(h)):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            return [[2 if left[r][j] != 0 and right[r][j] != 0 else 0
                     for j in range(len(left[0]))] for r in range(h)]

    return []
